CREATE TABLE IF NOT EXISTS am_users(id TEXT PRIMARY KEY,wallet TEXT UNIQUE,email TEXT UNIQUE,username TEXT NOT NULL,avatar TEXT NOT NULL DEFAULT '◈',chains TEXT NOT NULL DEFAULT '[]',private INTEGER NOT NULL DEFAULT 1,reputation INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS am_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS am_sessions_user ON am_sessions(user_id);
CREATE TABLE IF NOT EXISTS am_login_challenges(id TEXT PRIMARY KEY,address TEXT NOT NULL,chain INTEGER NOT NULL,origin TEXT NOT NULL,message TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS am_email_codes(id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS am_rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS am_posts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),project_id TEXT NOT NULL DEFAULT '',title TEXT NOT NULL,body TEXT NOT NULL,channel TEXT NOT NULL,chain TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'published',live INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS am_posts_channel ON am_posts(status,channel,created_at);
CREATE TABLE IF NOT EXISTS am_comments(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES am_posts(id),user_id TEXT NOT NULL REFERENCES am_users(id),parent_id TEXT REFERENCES am_comments(id),depth INTEGER NOT NULL DEFAULT 0,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS am_comments_post ON am_comments(post_id,created_at);
CREATE TABLE IF NOT EXISTS am_votes(user_id TEXT NOT NULL REFERENCES am_users(id),target_type TEXT NOT NULL,target_id TEXT NOT NULL,value INTEGER NOT NULL CHECK(value IN(-1,0,1)),PRIMARY KEY(user_id,target_type,target_id));
CREATE TABLE IF NOT EXISTS am_bookmarks(user_id TEXT NOT NULL REFERENCES am_users(id),post_id TEXT NOT NULL REFERENCES am_posts(id),PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS am_reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,evidence TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',resolution TEXT NOT NULL DEFAULT '',moderator TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,target_type,target_id));
CREATE INDEX IF NOT EXISTS am_reports_status ON am_reports(status,created_at);
CREATE TABLE IF NOT EXISTS am_reputation(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),reason TEXT NOT NULL,points INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS am_notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),type TEXT NOT NULL,payload TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS am_notifications_user ON am_notifications(user_id,created_at);
CREATE TABLE IF NOT EXISTS am_delivery_preferences(user_id TEXT PRIMARY KEY REFERENCES am_users(id),email INTEGER NOT NULL DEFAULT 0,telegram INTEGER NOT NULL DEFAULT 0,discord INTEGER NOT NULL DEFAULT 0,telegram_chat TEXT NOT NULL DEFAULT '',discord_webhook TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS am_delivery_queue(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),channel TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS am_delivery_due ON am_delivery_queue(status,next_at);
CREATE TABLE IF NOT EXISTS am_domains(host TEXT PRIMARY KEY,project_id TEXT NOT NULL,source TEXT NOT NULL,reviewed_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS am_public_quests(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,title TEXT NOT NULL,chain INTEGER NOT NULL,target TEXT NOT NULL,selector TEXT NOT NULL DEFAULT '',points INTEGER NOT NULL DEFAULT 25,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS am_quest_claims(user_id TEXT NOT NULL REFERENCES am_users(id),quest_id TEXT NOT NULL REFERENCES am_public_quests(id),tx_hash TEXT NOT NULL,chain INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,quest_id),UNIQUE(chain,tx_hash));
CREATE TABLE IF NOT EXISTS am_daily_usage(user_id TEXT NOT NULL,day TEXT NOT NULL,kind TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,day,kind));
CREATE TABLE IF NOT EXISTS am_moderation_log(id TEXT PRIMARY KEY,moderator TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO am_core_schema(version) VALUES(3);
CREATE TABLE IF NOT EXISTS am_holdings(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES am_users(id),symbol TEXT NOT NULL,chain TEXT NOT NULL,contract TEXT NOT NULL DEFAULT '',amount REAL NOT NULL,cost REAL NOT NULL DEFAULT 0,manual_price REAL,price_id TEXT NOT NULL DEFAULT '',claim_status TEXT NOT NULL DEFAULT 'pending',received_at TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS am_holdings_user ON am_holdings(user_id);
CREATE TABLE IF NOT EXISTS am_push_subscriptions(user_id TEXT NOT NULL REFERENCES am_users(id),endpoint TEXT PRIMARY KEY,subscription TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS am_user_tasks(user_id TEXT NOT NULL,project_id TEXT NOT NULL,task_id TEXT NOT NULL,status TEXT NOT NULL,completed_at TEXT,PRIMARY KEY(user_id,project_id,task_id));
CREATE TABLE IF NOT EXISTS am_delivery_cursor(id INTEGER PRIMARY KEY CHECK(id=1),last_user TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO am_delivery_cursor(id) VALUES(1);
